Method.Implementation:
s ipref=##class(User.Util).getClassPrefixParam(class)
s recPerPage=25  ; pres den ma API napevno nastaveno na 1
s bBreak=0
#dim req As %Net.HttpRequest
#dim iterator As %Iterator.Array
s req=..getHttpRequestCep()

s page=0
for i=1:1 {
  s page=page+1
  s bOKgcp=..getDataCep(ipref,.params,req,.obj,page,recPerPage)
  if 'bOKgcp || '$isobject(obj) {
    ; pri chybe ukoncime cely import at nepretezujeme API, maji nejake sledovani zateze
    s bBreak=1
  }

  if obj.hlavicka.kod="317" {
    w !,"empty result"
    q
  }

  w:i=1 !,"number of pages: "_obj.hlavicka.%Get("pocet-stran")
  w:i=1 !,"rec per page: "_obj.hlavicka.%Get("limit")
  w !,"page: "_page
  w !,"find records: "_obj.hlavicka.%Get("pocet-vysledku")

  if $ISOBJECT(obj.data) {
    s iterator=obj.data.%GetIterator()
    while iterator.%GetNext(.key, .value) {
      s projektId=..obj2HandleCep(.handle,class,.value,.icoUstavAll,.poskytovatel)
      continue:projektId=""  ; bez cisla projektu nejsme schopni dohledat/deduplikovat

      // Test only
      //if (projektId'="EH22_008/0004624")&&(projektId'="GA24-10013S") { continue }
      //w !!,value.%ToJSON(),!!

      s idRec=##class(User.MARC).getIDByIndex(class,"proj",$zcvt(projektId,"l"))
      s t001Rec=""
      s:idRec t001Rec=##class(User.MARC).getT001(idRec)
      d ..synchCavDbAuth(class,.handle,t001Rec,bTestOnly)
    }
  }

  q:page>=obj.hlavicka.%Get("pocet-stran")
  hang 2 ; pauza mezi strankami
}

; pro poradek procistime FormData pro dalsi dotaz
s par=""
for {
  s par=$o(params(par))
  q:par=""
  d req.DeleteFormData(par)
}

; musi se plnit znovu pred kazdym provolanim s token=..getToken(ipref) d req.SetHeader("token",token) d req.InsertFormData("token",token) d req.InsertFormData("oblast","cep") d req.InsertFormData("rezim","filtr-detail") d req.InsertFormData("format","json") d req.InsertFormData("limit",recPerPage) d req.InsertFormData("page",1) d req.InsertFormData("finance",1) d req.InsertFormData("strana",page) s par="" for { ; doplnime selekcni parametry s par=$o(params(par),1,val) q:par="" d req.InsertFormData(par,val) ; napr. req.InsertFormData("pd-org-ico","68081758") }
s sc=req.Post("/api.php") if $$$ISERR(sc) { w !,"ERROR getDataCep Net.HttpRequest API VAVAI http post:"_##class(User.Util).status2str(sc) q 0 }
if ((req.HttpResponse.StatusCode'="200") ) { w !,"ERROR getDataCep %Net.HttpRequest API VAVAI http status code: "_req.HttpResponse.StatusCode_" "_req.HttpResponse.StatusLine q 0 }
s streamHttp=req.HttpResponse.Data s response=streamHttp.Read(streamHttp.Size)
s obj=##class(%DynamicAbstractObject).%FromJSON(response) if '$isobject(obj) { w !,"ERROR getDataCep %Net.HttpRequest API VAVAI unexpected no JSON response" q 0 }
s hlavicka=obj.hlavicka ; %DynamicObject if '$isobject(hlavicka) { w !,"ERROR getDataCep %Net.HttpRequest API VAVAI unexpected response, no find object 'hlavicka'" q 0 }
if (hlavicka.kod'="200") && (hlavicka.kod'="317") { //d $system.OBJ.Dump(hlavicka) w !,"ERROR getDataCep %Net.HttpRequest API VAVAI response" w !," kod: "_hlavicka.kod w !," zprava: "_hlavicka.zprava w !," pocet-vysledku: "_hlavicka.%Get("pocet-vysledku") w !," limit: "_hlavicka.limit w !," pocet-stran: "_hlavicka.%Get("pocet-stran") w !," strana: "_hlavicka.strana w !," finance: "_hlavicka.finance w !," verze: "_hlavicka.verze q 0 }
q 1


s ret=""
d ##class(User.MARC).newX(.handle,class,"new")

if ##class(User.MARC).readX(.handleVzor,##class(User.Util).getClassPrefixParam(class)_"UnTablesd","GEN_VAVAI_REC")
{   
  ; prvotni naplneni handlu dle vzoru
  s nC=##class(User.MARC).recordLineCountX(.handleVzor) ; ziskani poctu radku v zaznamu 
  f i=1:1:nC 
  { ; pres vsechny radky zaznamu pujdeme po jednom radku a budeme nahrazovat
    s lsLine=##class(User.MARC).getLineX(.handleVzor,i) continue:lsLine="" 
    s sTag=$e(lsLine,1,3)                               ; ziskani tagu
    continue:((sTag="002")||(sTag="999"))               ; 002 do zaznamu nezapisujeme
    s:(sTag="005") lsLine=##class(User.MARC).genT005(1) ; vygenerujeme novou 005

    ; musime provest nahrazeni v handlu
    s lsLine=$replace(lsLine,"%DATEYYYYMMDD%",$ZDATE($horolog,8))
    s lsLine=$replace(lsLine,"%DATEDD.MM.YYYY%",($e($ZDATE($horolog,8),7,8)_"."_$e($ZDATE($horolog,8),5,6)_"."_$e($ZDATE($horolog,8),1,4)))
    s lsLine=$replace(lsLine,"%DATEYYMMDD% ",$e($ZDATE($horolog,8),3,8))    
    s lsLine=$$$strswap(lsLine,$c(31)_$c(31),$c(31))

    d ##class(User.MARC).appendLineX(.handle,lsLine) ; zapsani radku do autority
  }    
  d ##class(User.MARC).recordDelEmptyST(.handle)     ; odmazani prazdnych subtagu
}  

