    }

    if $ISOBJECT(val1.resitele) {
      s it2=val1.resitele.%GetIterator()
      while it2.%GetNext(.key2,.val2) {
        s idxRecR=""   ; link na resitele C35$3
        s rivId=val2.vedidk
        s orcId=val2.orcid
        s scopusId=val2.scopusid
        //s researcherId=val2.researcherid  ; nepouzivame, nenasel jsem v datech 035

        ; dohledani autora
        ; - musi se najit podle jmena, prijmeni a ustavu 
        ; -- pokud se najde jeden je to OK, ale muze byt vice stejneho jmena, pouziji se identifikatory, nebo se nakonec vezme posledni nalezeny
        ; -- pokud se nenajde, link se nedoplni (jeden autor muze v case menit ustavy, to pak ma pro kazdy ustav jiny aut. zaznam ale nas zajima jen ten spojeny se zpracovavanym ustavem)
        s aupra=$zcvt(val2.prijmeni_" "_val2.jmeno_"  "_icoUstavAll(icoP),"l")
        s idRecR=0
        s node=""
        for {
          s node=##class(User.MARC).getIDByIndex(class,"aupra",aupra,node)
          q:node=0

          s idRecR=node
          s idRecRbyID=0
          if (rivId'="")  { s idRecRbyID=##class(User.MARC).getIDByIndex(class,"ida","rivid "_rivId) }
          if (idRecR="") && (orcId'="")  { s idRecRbyID=##class(User.MARC).getIDByIndex(class,"ida","orcid "_orcId) }
          if (idRecR="") && (scopusId'="") { s idRecRbyID=##class(User.MARC).getIDByIndex(class,"ida","scopus "_scopusId) }
          if idRecR=idRecRbyID { q }  ; mame overeno i podle identifikatoru
        }
        if idRecR {
          s t001RecR=##class(User.MARC).getT001(idRecR)
          s idxRecR=lname_"*"_t001RecR
        } 

        s sC35="C35    "
        s:idxRecR'="" sC35=sC35_$c(31)_"3"_idxRecR
        s:val2.prijmeni'="" sC35=sC35_$c(31)_"a"_val2.prijmeni
        s:val2.jmeno'="" sC35=sC35_$c(31)_"b"_val2.jmeno

        if $l(sC35)>7 {
          s:$l(sC35All)>7 sC35All=sC35All_$c(10)
          s sC35All=sC35All_sC35
        }
      }
    }
  }
}

