s s230a=##class(User.MARC).getTagX(.handleN,"230a")  ; nazev projektu
s s230h=##class(User.MARC).getTagX(.handleN,"230h")  ; id projektu

w !!,"-----------------------------------------------------------------------------------------------"
w !,"Project ID: "_s230h
w !,s230a

if (t001Rec'="") && (##class(User.MARC).readX(.handle,class,t001Rec)) {
  w !,"update local record t001="_t001Rec
  if bTestOnly { w !," test only, without saving changes" }

  s bHandleChange=0

  /* POKUS O VYUZITI HANDLE MERGE - moc to nefungovalo 
  ; priprava handlu pro porovnani a merge, vlozime do nej jen tagy co se plni v obj2HandleCep
  m h2m=handle
  s s230=##class(User.MARC).getTagX(.handleN,"230")
  s s430=##class(User.MARC).getTagX(.handleN,"430")
  s sC28=##class(User.MARC).getTagX(.handleN,"C28")
  s sC29=##class(User.MARC).getTagX(.handleN,"C29")
  s sC31=##class(User.MARC).getTagX(.handleN,"C31",-1)
  s sC35=##class(User.MARC).getTagX(.handleN,"C35",-1)
  s sC47=##class(User.MARC).getTagX(.handleN,"C47")
  d ##class(User.MARC).delTagX(.h2m,"230") d ##class(User.MARC).setTagX(.h2m,s230)
  d ##class(User.MARC).delTagX(.h2m,"430") d ##class(User.MARC).setTagX(.h2m,s430)
  d ##class(User.MARC).delTagX(.h2m,"C28") d ##class(User.MARC).setTagX(.h2m,sC28)
  d ##class(User.MARC).delTagX(.h2m,"C29") d ##class(User.MARC).setTagX(.h2m,sC29)
  d ##class(User.MARC).delTagX(.h2m,"C31") d ##class(User.MARC).setTagX(.h2m,sC31)
  d ##class(User.MARC).delTagX(.h2m,"C35") d ##class(User.MARC).setTagX(.h2m,sC35)
  ;d ##class(User.MARC).delTagX(.h2m,"C47") d ##class(User.MARC).setTagX(.h2m,sC47)
  d ##class(util.compare).MARCcompare(.h2m,.handle,.changes,0)
  ; ze zmen vyhodime vsechny delete zmeny
  m tmp=changes k changes s changes=""
  s nd=""
  for {
    s nd=$o(tmp(nd))
    q:nd=""
    continue:$p(nd,",")="D"

    s changes(nd)=""
  }
  s err=##class(util.compare).merge(.handle,.changes,.outH)
  if err'="" {
    w !," ERROR update record: "_err
  }
  d ..writeHandleOutput(.h2m,"Vavai CEP record: ")
  d ..writeHandleOutput(.handle,"ASEP updated record: ")
  */


  ; ukladame jen to co se ziskava v obj2HandleCep, je potreba to tedy udrzovat mezi sebou synchronizovane

  ; nejdrive bez opakovani poli, podpole se mohou opakovat ale zalezi na poradi
  s changes("230")="a,b,h"
  s changes("430")="a"
  s changes("C28")="a"
  s changes("C29")="a,b"
  s nd1=""
  for {
    s nd1=$o(changes(nd1))
    q:nd1=""

    s bTagChange=0
    s tag=##class(User.MARC).getTagX(.handleN,nd1)
    s tagDb=##class(User.MARC).getTagX(.handle,nd1)
    s tagDbOrig=tagDb

    s str=$g(changes(nd1))
    for i=1:1:$l(str,",") {
      s subTagName=$p(str,",",i)
      continue:subTagName=""

      s val=##class(User.MARC).getSubTagStr(tag,subTagName,-1)       ; takto umime zpracovat vice opakovani jednoho podpole
      s valDb=##class(User.MARC).getSubTagStr(tagDb,subTagName,-1)   ; takto umime zpracovat vice opakovani jednoho podpole

      if (val'="") && (val'=valDb) {
        s tagDb=##class(User.MARC).setSubTagStr(tagDb,val,nd1_"    "_$c(31)_subTagName)
        d ##class(User.MARC).setTagX(.handle,tagDb)
        s (bTagChange,bHandleChange)=1
      }

    }

    if bTagChange {
      w !,"    "_$replace(tagDbOrig,$c(31),"$$")
      w !," -> "_$replace(tagDb,$c(31),"$$"),!,"    ---"

    }      
  } 

  ; C31 - jednoduche porovnani celych retezcu
  s sC31All=##class(User.MARC).getTagX(.handleN,"C31",-1)
  s sC31AllDb=##class(User.MARC).getTagX(.handle,"C31",-1)
  if (sC31All'=sC31AllDb) && ($l(sC31All)>=$l(sC31AllDb)) && ($l(sC31All,$c(10))>=$l(sC31AllDb,$c(10))) {
    ; pokud je tam nejaka zmena a pocet opakovani poli je stejny nebo vetsi, a nezkratila se celkova delka tak se aktualizuje
    ; - je to jen priblizne
    d ##class(User.MARC).setTagX(.handle,sC31All)
    w !,"    "_$replace($replace(sC31AllDb,$c(31),"$$"),$c(10),$c(13,10)_"    ")
    w !," -> "_$replace($replace(sC31All,$c(31),"$$"),$c(10),$c(13,10)_"    "),!,"    ---"
    s bHandleChange=1
  }

  ; C35 - jednoduche porovnani celych retezcu
  s sC35All=##class(User.MARC).getTagX(.handleN,"C35",-1)
  s sC35AllDb=##class(User.MARC).getTagX(.handle,"C35",-1)
  if (sC35All'=sC35AllDb) && ($l(sC35All)>=$l(sC35AllDb)) && ($l(sC35All,$c(10))>=$l(sC35AllDb,$c(10))) {
    ; pokud je tam nejaka zmena a pocet opakovani poli je stejny nebo vetsi, a nezkratila se celkova delka tak se aktualizuje
    ; - je to jen priblizne
    d ##class(User.MARC).setTagX(.handle,sC35All)
    w !,"    "_$replace($replace(sC35AllDb,$c(31),"$$"),$c(10),$c(13,10)_"    ")
    w !," -> "_$replace($replace(sC35All,$c(31),"$$"),$c(10),$c(13,10)_"    "),!,"    ---"
    s bHandleChange=1
  }

  ; cav: neprebirat
  ; C47 - dve opakovani pole, resime v nich je jedno opakovani $$d
  /*s sC47=##class(User.MARC).getTagX(.handleN,"C47",-1)
  if sC47'="" {
    s sC47d1=##class(User.MARC).getSubTagStr($p(sC47,$c(10),1),"d")      ; $$d z prvniho opak. C47
    s sC47d2=##class(User.MARC).getSubTagStr($p(sC47,$c(10),2),"d")      ; $$d ze druheho opak. C47
    s sC47Db=##class(User.MARC).getTagX(.handle,"C47",-1)
    s sC47d1Db=##class(User.MARC).getSubTagStr($p(sC47Db,$c(10),1),"d")  ; $$d z prvniho opak. C47
    s sC47d2Db=##class(User.MARC).getSubTagStr($p(sC47Db,$c(10),2),"d")  ; $$d ze druheho opak. C47
    s sC47new=""
    ; kontrola prvniho opakovani
    if (sC47d1'="")&&(sC47d1'=sC47d1Db) { 
      s sC47new=##class(User.MARC).setSubTagStr($p(sC47Db,$c(10),1),sC47d1,"C47    "_$c(31)_"d") 
    }
    elseif sC47Db'="" { 
      s sC47new=$p(sC47Db,$c(10),1) ; vratit prvni opakovani C47 bez zmeny
    } 
    ; kontrola druheho opakovani
    if (sC47d2'="")&&(sC47d2'=sC47d2Db) {
      s:sC47new'="" sC47new=sC47new_$c(10)
      s sC47new=sC47new_##class(User.MARC).setSubTagStr($p(sC47Db,$c(10),2),sC47d2,"C47    "_$c(31)_"d")
    }
    elseif $p(sC47Db,$c(10),2)'="" {
      s:sC47new'="" sC47new=sC47new_$c(10)
      s sC47new=sC47new_$p(sC47Db,$c(10),2) ; vratit druhe opakovani C47 bez zmeny
    }
    ; zapsani zmen
    if (sC47Db'=sC47new) {
      d ##class(User.MARC).setTagX(.handle,sC47new)
      w !,"    "_$replace($replace(sC47Db,$c(31),"$$"),$c(10),$c(13,10)_"    ")
      w !," -> "_$replace($replace(sC47new,$c(31),"$$"),$c(10),$c(13,10)_"    "),!,"    ---"
      s bHandleChange=1
    } 
  }*/



  if bHandleChange {
    //d ..writeHandleOutput(.handle,"Update record: ")  ; jen pro pripadnou kontrolu celeho zaznamu, zmeny se vypisuji coz by melo stacit
    if bTestOnly { 
      w !," test only, without saving changes" 
    }
    else {
      d ##class(User.MARC).sortLinesX(.handle)
      s sChronMode=3_$c(10)_"arl"_$c(10)_" Import projektů z db VaVaI CEP do autorit ASEP"_" - ##class(util.ie.vavai).importCavCep()"
      s sc=##class(User.MARC).writeX(.handle,,,,sChronMode)
      if $$$ISERR(sc) {
        w !,"ERROR insert new record, msg="_##class(User.Util).status2str(sc)
      }
      else {
        w !," - successfully, record "_$$$HandleClass(handle)_"/"_$$$HandleT001(handle)
      }
    }
  }
  else {
    w !," no changes"
  }    
}
else {
  w !,"insert new record"
  d ..writeHandleOutput(.handleN,"New record: ")  ; vypsat cely bovy zaznam
  if bTestOnly { 
    w !," test only, without saving changes" 
  }
  else {
    d ##class(User.MARC).sortLinesX(.handleN)
    s sChronMode=3_$c(10)_"arl"_$c(10)_" Import projektů z db VaVaI CEP do autorit ASEP"_" - ##class(util.ie.vavai).importCavCep()"
    s sc=##class(User.MARC).writeX(.handleN,,,,sChronMode)
    if $$$ISERR(sc) {
      w !,"ERROR insert new record, msg="_##class(User.Util).status2str(sc)
    }
    else {
      w !," - successfully, record "_$$$HandleClass(handleN)_"/"_$$$HandleT001(handleN)
    }
  }
}

w !,"util.ie.vavai.testCep start at "_$zdt($h,3)
w !," ipref: "_ipref
w !

s class=ipref_"UnAuth"

s icoUstavAll="" ; seznam ICO vsech ustavu, vyuzivaji podmetody
s untablesd=##class(User.Util).getClassPrefixParam(class)_"UnTablesd"
d ##class(User.MARC).readX(.hPra,untablesd,"CAV_PRA")
s c=0
do {
  s s200=##class(User.MARC).getTagX(.hPra,"200",.c)
  continue:s200=""
  s icoU=##class(User.MARC).getSubTagStr(s200,"g")
  continue:icoU=""

  s icoUstavAll(icoU)=##class(User.MARC).getSubTagStr(s200,"a")
} while c'=0

s poskytovatel="" ; pole pro preklad kodu poskytovatele podle EPC_POSKYTOVATEL_CEP
d ..prepare(class,.poskytovatel)

s recPerPage=1, page=1
s req=..getHttpRequestCep()
//s params("fp-poskytovatel")="AV0"          ; min. jedno selekni kriterium
//s params("pr-kod-fix")="EH22_008/0004624"    ; CavUnAuth t001=0466793  pole 230h
//s params("pr-kod-fix")="GA24-10662S"         ; CavUnAuth t001=0465905
//s params("pr-kod-fix")="LL2402"              ; CavUnAuth t001=0471297
//s params("pr-kod-fix")="GA24-12229S"         ; CavUnAuth t001=0465897
//s params("pr-kod-fix")="SS07020400"          ; CavUnAuth t001=0468598   autor Konvickova nalezeny jiny podle RIVid mel by to byt ok
//s params("pr-kod-fix")="GA24-13058S"
s params("pr-kod-fix")="GA24-10000S"  ; ustav jako dalsi ucastnik


s bOKgcp=..getDataCep(ipref,.params,req,.obj,page,recPerPage)

if bOKgcp { 
  w ! zw obj.%ToJSON() 
  if $ISOBJECT(obj.data) {
    s iterator=obj.data.%GetIterator()
    while iterator.%GetNext(.key, .value) {
      s projektId=..obj2HandleCep(.handle,class,.value,.icoUstavAll,.poskytovatel)

      continue:projektId=""  ; bez cisla projektu nejsme schopni dohledat/deduplikovat

      s idRec=##class(User.MARC).getIDByIndex(class,"proj",$zcvt(projektId,"l"))
      s t001Rec=""
      s:idRec t001Rec=##class(User.MARC).getT001(idRec)
      d ..synchCavDbAuth(class,.handle,t001Rec,1)

    }
  }
}

w !,"util.ie.vavai.testCep finished at "_$zdt($h,3),!

d ##class(User.MARC).sortLinesX(.handle)
w !,"----------------------------------------------" w !,pText_$g(handle("class"))_"*"_$g(handle("t001"))
for j=1:1:10 { ; jdeme pres 10 uzlu recordu, to by melo stacit continue:($g(handle("Rec",j))="") for i=1:1:$l(handle("Rec",j),$c(10)) { ; vypis jednotlivych tagu s line=$p(handle("Rec",j),$c(10),i) w !,$$$strswap(line,$c(31),"$$") } }
